/**
 * `talki.calls`: Read the calls answered by Talki and their transcripts, file them, count and export
 * them, and read the calls Talki refused.
 *
 * Each method sends one operation and returns its value, or throws the `ApiError` subclass for its
 * error.
 */
export class CallsResource {
  /** The same methods, each returning the whole answer: its status and headers with the value. */
  readonly withRawResponse: CallsResourceWithRawResponse;

  constructor(requester: Requester) {
    this.withRawResponse = new CallsResourceWithRawResponse(requester);
  }

  /**
   * Count calls
   *
   * Count the calls in one inbox view. `status=unread` is the unread badge. Requires `calls:read`.
   * Limited to 600 requests per minute per account (API key) or per installation (OAuth).
   *
   * @param params - the query, body and options; see `CountCallsParams`.
   * @see GET /v1/calls/count
   */
  async count(params: CountCallsParams = {}): Promise<CountCallsResponse> {
    return (await this.withRawResponse.count(params)).data;
  }

  /**
   * Count refused calls
   *
   * Count every refused call the account has. Requires `calls:read`. Limited to 600 requests per
   * minute per account (API key) or per installation (OAuth).
   *
   * @param params - the query, body and options; see `CountRefusedCallsParams`.
   * @see GET /v1/refused_calls/count
   */
  async countRefused(params: CountRefusedCallsParams = {}): Promise<CountRefusedCallsResponse> {
    return (await this.withRawResponse.countRefused(params)).data;
  }

  /**
   * Delete a call
   *
   * Delete a call for good, when the caller asks to be forgotten: the call, its transcript, the
   * questions it left and the pending contacts it proposed. The appointments it booked stay, with
   * `call_id` null. The talk time it used stays on the meter of `GET /v1/usage` and, for a
   * partner-managed account, in the partner's usage report; `GET /v1/usage/history` and the call
   * statistics no longer count the call. Sends `call.deleted`. Requires `calls:delete`. Limited to 120
   * requests per minute per account (API key) or per installation (OAuth).
   *
   * @param callId - call_id
   * @param params - the query, body and options; see `DeleteCallParams`.
   * @see DELETE /v1/calls/{call_id}
   */
  async delete(callId: string, params: DeleteCallParams = {}): Promise<DeleteCallResponse> {
    return (await this.withRawResponse.delete(callId, params)).data;
  }

  /**
   * Export a call
   *
   * Return one call as a PDF or Excel file, on every plan. It includes the conversation only with
   * `transcripts:read` and when the account keeps transcripts, and the call's appointments only with
   * `appointments:read`. Requires `calls:read`. Limited to 600 requests per minute per account (API
   * key) or per installation (OAuth), and to 10 file exports per minute.
   *
   * @param callId - call_id
   * @param params - the query, body and options; see `ExportCallParams`.
   * @see GET /v1/calls/{call_id}/export
   */
  async exportCall(callId: string, params: ExportCallParams = {}): Promise<ExportCallResponse> {
    return (await this.withRawResponse.exportCall(callId, params)).data;
  }

  /**
   * Export the call log
   *
   * Return the calls of a date range as a PDF or Excel file, without transcripts. `status` defaults to
   * `all`; `status`, `q` and `outcome` narrow the file as they narrow `GET /v1/calls`. Each call's
   * appointments are included only when the credential also holds `appointments:read`. Needs a plan
   * that includes the call log export. Requires `calls:read`. Limited to 600 requests per minute per
   * account (API key) or per installation (OAuth), and to 10 file exports per minute.
   *
   * @param params - the query, body and options; see `ExportCallsParams`.
   * @see GET /v1/calls/export
   */
  async exportCalls(params: ExportCallsParams): Promise<ExportCallsResponse> {
    return (await this.withRawResponse.exportCalls(params)).data;
  }

  /**
   * Retrieve a call
   *
   * Return one call belonging to the authenticated account. Requires `calls:read`. Limited to 600
   * requests per minute per account (API key) or per installation (OAuth).
   *
   * @param callId - call_id
   * @param params - the query, body and options; see `GetCallParams`.
   * @see GET /v1/calls/{call_id}
   */
  async get(callId: string, params: GetCallParams = {}): Promise<GetCallResponse> {
    return (await this.withRawResponse.get(callId, params)).data;
  }

  /**
   * Summarise refused calls
   *
   * Return refused calls over the last `days`, or over the local days `from` to `to`, by reason, and
   * the actions they call for. Requires `calls:read`. Limited to 600 requests per minute per account
   * (API key) or per installation (OAuth).
   *
   * @param params - the query, body and options; see `GetRefusedCallSummaryParams`.
   * @see GET /v1/refused_calls/summary
   */
  async getRefusedSummary(params: GetRefusedCallSummaryParams = {}): Promise<GetRefusedCallSummaryResponse> {
    return (await this.withRawResponse.getRefusedSummary(params)).data;
  }

  /**
   * Retrieve call statistics
   *
   * Return totals, the daily series and the top callers over the last `days`, or over the local days
   * `from` to `to` (at most 366). Requires `calls:read`. Limited to 600 requests per minute per
   * account (API key) or per installation (OAuth).
   *
   * @param params - the query, body and options; see `GetCallStatsParams`.
   * @see GET /v1/calls/stats
   */
  async getStats(params: GetCallStatsParams = {}): Promise<GetCallStatsResponse> {
    return (await this.withRawResponse.getStats(params)).data;
  }

  /**
   * Retrieve a call transcript
   *
   * Return the automatic transcript of one call. `calls:read` does not grant it: the account owner
   * ticks `transcripts:read` on its own. Requires `transcripts:read`. Limited to 600 requests per
   * minute per account (API key) or per installation (OAuth).
   *
   * @param callId - call_id
   * @param params - the query, body and options; see `GetCallTranscriptParams`.
   * @see GET /v1/calls/{call_id}/transcript
   */
  async getTranscript(callId: string, params: GetCallTranscriptParams = {}): Promise<GetCallTranscriptResponse> {
    return (await this.withRawResponse.getTranscript(callId, params)).data;
  }

  /**
   * List calls
   *
   * Read the newest-first call log, or set `sync=true` for a resumable change feed. Search the log
   * with `phone`, `contact_id`, `q` or `outcome`; they do not combine with `sync=true`. Requires
   * `calls:read`. Limited to 600 requests per minute per account (API key) or per installation
   * (OAuth).
   *
   * @param params - the query, body and options; see `ListCallsParams`.
   * @see GET /v1/calls
   */
  list(params: ListCallsParams = {}): PagePromise<ListCallsRow> {
    return new PagePromise(async () => (await this.withRawResponse.list(params)).data);
  }

  /**
   * List refused calls
   *
   * Return the calls Talki refused before answering, newest first. Requires `calls:read`. Limited to
   * 600 requests per minute per account (API key) or per installation (OAuth).
   *
   * @param params - the query, body and options; see `ListRefusedCallsParams`.
   * @see GET /v1/refused_calls
   */
  listRefused(params: ListRefusedCallsParams = {}): PagePromise<ListRefusedCallsRow> {
    return new PagePromise(async () => (await this.withRawResponse.listRefused(params)).data);
  }

  /**
   * Mark all calls read
   *
   * Mark every unread call in the inbox read. Each one sends `call.updated`. Requires `calls:write`.
   * Limited to 120 requests per minute per account (API key) or per installation (OAuth).
   *
   * @param params - the query, body and options; see `MarkAllCallsReadParams`.
   * @see POST /v1/calls/mark_all_read
   */
  async markAllRead(params: MarkAllCallsReadParams = {}): Promise<MarkAllCallsReadResponse> {
    return (await this.withRawResponse.markAllRead(params)).data;
  }

  /**
   * Update a call's inbox state
   *
   * Mark a call read or unread, archive it or return it to the inbox. Archiving marks it read.
   * Requires `calls:write`. Limited to 120 requests per minute per account (API key) or per
   * installation (OAuth).
   *
   * @param callId - call_id
   * @param params - the query, body and options; see `UpdateCallParams`.
   * @see PATCH /v1/calls/{call_id}
   */
  async update(callId: string, params: UpdateCallParams): Promise<UpdateCallResponse> {
    return (await this.withRawResponse.update(callId, params)).data;
  }
}

