/** One attribute per resource, each built on first use. `Talki` extends it. */
export class Resources {
  readonly #requester: Requester;
  #account: AccountResource | undefined;
  #locations: LocationsResource | undefined;
  #usage: UsageResource | undefined;
  #voices: VoicesResource | undefined;
  #workingHours: WorkingHoursResource | undefined;
  #closures: ClosuresResource | undefined;
  #calls: CallsResource | undefined;
  #appointments: AppointmentsResource | undefined;
  #contacts: ContactsResource | undefined;
  #pendingContacts: PendingContactsResource | undefined;
  #tags: TagsResource | undefined;
  #callerRules: CallerRulesResource | undefined;
  #services: ServicesResource | undefined;
  #resources: ResourcesResource | undefined;
  #unresolvedRequests: UnresolvedRequestsResource | undefined;
  #availability: AvailabilityResource | undefined;
  #sandbox: SandboxResource | undefined;

  constructor(requester: Requester) {
    this.#requester = requester;
  }

  /**
   * Validate a credential, identify its Talki account, change the assistant's settings, set up call
   * forwarding and finish onboarding.
   */
  get account(): AccountResource {
    this.#account ??= new AccountResource(this.#requester);
    return this.#account;
  }

  /**
   * List the places the business works from, each with its own Talki number and line.
   */
  get locations(): LocationsResource {
    this.#locations ??= new LocationsResource(this.#requester);
    return this.#locations;
  }

  /**
   * Read the talk time used and left in the current period.
   */
  get usage(): UsageResource {
    this.#usage ??= new UsageResource(this.#requester);
    return this.#usage;
  }

  /**
   * List the voices the assistant can speak with, and fetch a sample of each.
   */
  get voices(): VoicesResource {
    this.#voices ??= new VoicesResource(this.#requester);
    return this.#voices;
  }

  /**
   * Read and replace the weekly opening hours.
   */
  get workingHours(): WorkingHoursResource {
    this.#workingHours ??= new WorkingHoursResource(this.#requester);
    return this.#workingHours;
  }

  /**
   * List, add, change and remove the dated closures and special openings that override the weekly
   * hours.
   */
  get closures(): ClosuresResource {
    this.#closures ??= new ClosuresResource(this.#requester);
    return this.#closures;
  }

  /**
   * Read the calls answered by Talki and their transcripts, file them, count and export them, and read
   * the calls Talki refused.
   */
  get calls(): CallsResource {
    this.#calls ??= new CallsResource(this.#requester);
    return this.#calls;
  }

  /**
   * Sync, create, reschedule and cancel bookings.
   */
  get appointments(): AppointmentsResource {
    this.#appointments ??= new AppointmentsResource(this.#requester);
    return this.#appointments;
  }

  /**
   * Sync, upsert and delete curated address-book contacts.
   */
  get contacts(): ContactsResource {
    this.#contacts ??= new ContactsResource(this.#requester);
    return this.#contacts;
  }

  /**
   * Approve or discard the names the assistant heard on calls.
   */
  get pendingContacts(): PendingContactsResource {
    this.#pendingContacts ??= new PendingContactsResource(this.#requester);
    return this.#pendingContacts;
  }

  /**
   * Label contacts.
   */
  get tags(): TagsResource {
    this.#tags ??= new TagsResource(this.#requester);
    return this.#tags;
  }

  /**
   * Manage the VIP and blocked numbers, and read the calls the block refused.
   */
  get callerRules(): CallerRulesResource {
    this.#callerRules ??= new CallerRulesResource(this.#requester);
    return this.#callerRules;
  }

  /**
   * Sync the service catalogue, create a service with a fixed duration, update a service's name,
   * description, price, duration or active state, and delete a service with no bookings still to come.
   */
  get services(): ServicesResource {
    this.#services ??= new ServicesResource(this.#requester);
    return this.#services;
  }

  /**
   * Read the capacity a business books against, create a shared resource, rename a resource or change
   * a shared resource's capacity, and delete a resource that is neither the default nor the only one a
   * service draws on.
   */
  get resources(): ResourcesResource {
    this.#resources ??= new ResourcesResource(this.#requester);
    return this.#resources;
  }

  /**
   * Follow, resolve and dismiss the questions the assistant could not answer, and teach the assistant
   * the answer for the next caller.
   */
  get unresolvedRequests(): UnresolvedRequestsResource {
    this.#unresolvedRequests ??= new UnresolvedRequestsResource(this.#requester);
    return this.#unresolvedRequests;
  }

  /**
   * Find bookable windows before creating an appointment.
   */
  get availability(): AvailabilityResource {
    this.#availability ??= new AvailabilityResource(this.#requester);
    return this.#availability;
  }

  /**
   * Drive a developer sandbox: tell it it had a call, and reset it to a known state. These endpoints
   * answer 404 on a real Talki account.
   */
  get sandbox(): SandboxResource {
    this.#sandbox ??= new SandboxResource(this.#requester);
    return this.#sandbox;
  }
}

/** Every resource and its methods: the public surface a test pins. */
export const SURFACE = {
  account: ["completeOnboarding", "get", "getForwardingCheck", "startForwardingCheck", "update"],
  locations: ["list"],
  usage: ["get", "getHistory"],
  voices: ["getPreview", "list"],
  workingHours: ["get", "replace"],
  closures: ["create", "delete", "list", "update"],
  calls: ["count", "countRefused", "delete", "exportCall", "exportCalls", "get", "getRefusedSummary", "getStats", "getTranscript", "list", "listRefused", "markAllRead", "update"],
  appointments: ["cancel", "create", "get", "list", "reschedule", "restore"],
  contacts: ["delete", "get", "list", "upsert"],
  pendingContacts: ["approve", "discard", "list"],
  tags: ["create", "delete", "list", "tagContact", "untagContact", "update"],
  callerRules: ["create", "delete", "list", "listBlockedCallAttempts", "update"],
  services: ["create", "delete", "get", "list", "update"],
  resources: ["create", "delete", "get", "list", "update"],
  unresolvedRequests: ["get", "list", "teach", "update"],
  availability: ["get"],
  sandbox: ["createCall", "listScenarios", "reset"],
} as const;
